<?php
 function safe_strtotime($datetime, $baseTimestamp = null) { return \strtotime($datetime ?? '', $baseTimestamp); } function safe_strlen($string) { return \strlen($string ?? ''); } function safe_json_decode($json, $associative = null, $depth = 512, $flags = 0) { return \json_decode($json ?? '', $associative, $depth, $flags); } function safe_date_create($datetime = "now", $timezone = null) { return \date_create($datetime ?? "now", $timezone); } function safe_strpos($haystack, $needle, $offset = 0) { return \strpos($haystack ?? '', $needle ?? '', $offset ?? 0); } function safe_explode($separator, $string, $limit = PHP_INT_MAX) { return \explode($separator ?? '', $string ?? '', $limit ?? PHP_INT_MAX); } function safe_str_replace($search, $replace, $subject, &$count = null) { return \str_replace($search ?? '', $replace ?? '', $subject ?? '', $count); } 